// Calcula intervalo da semana atual (seg → sex)
const now = new Date();
const dow = now.getDay(); // 0=Dom 1=Seg...
const monday = new Date(now);
monday.setDate(now.getDate() - (dow === 0 ? 6 : dow - 1));
monday.setHours(0, 0, 0, 0);
const friday = new Date(monday);
friday.setDate(monday.getDate() + 4);

const toISO = d => d.toISOString().split('T')[0];
return [{ json: { monday: toISO(monday), friday: toISO(friday) } }];

// Monta resumo semanal agrupado por dia
const appointments = $input.first().json;
const { monday } = $('Calcular semana').first().json;

const DAYS = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];

// Gera os 5 dias da semana
const days = [];
for (let i = 0; i < 5; i++) {
  const d = new Date(monday + 'T12:00:00');
  d.setDate(d.getDate() + i);
  days.push(d);
}

let msg = '📋 *Sua semana, Michele!*\n\n';
let total = 0;
let revenue = 0;

for (const day of days) {
  const iso = day.toISOString().split('T')[0];
  const dd  = String(day.getDate()).padStart(2,'0');
  const mm  = String(day.getMonth() + 1).padStart(2,'0');
  const label = `${DAYS[day.getDay()]}, ${dd}/${mm}`;
  const appts = (Array.isArray(appointments) ? appointments : []).filter(a => a.date === iso);

  msg += `*${label}*\n`;
  if (appts.length === 0) {
    msg += '_Nenhum agendamento_\n';
  } else {
    for (const a of appts) {
      msg += `🕐 ${a.start_time.slice(0,5)} ${a.client_name} — ${a.service_name}\n`;
      total++;
      revenue += Number(a.service_price ?? 0);
    }
  }
  msg += '\n';
}

const revenueStr = revenue.toFixed(2).replace('.',',');
msg += `📊 *Total: ${total} atendimento${total !== 1 ? 's' : ''} · R$ ${revenueStr}*`;

return [{ json: { message: msg } }];
